using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
namespace LWS.TruckSports.Editor {
public static class SheepMotionAuthoring {
 const string Model="Assets/TruckCheeseRolling/Art/Sheep/SheepV5.fbx",Root="Assets/TruckSports/Animations/";
 public static void Install(GameObject sheep,Transform mover){Directory.CreateDirectory(Root);var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Root+"Sheep locomotion.controller");if(controller==null)controller=Create();var skin=sheep.GetComponentInChildren<SkinnedMeshRenderer>(true);if(skin==null)throw new Exception("Genuine rigged SheepV5 missing");Transform model=skin.transform;while(model.parent!=null&&model.parent!=sheep.transform&&model.name!="SheepV5")model=model.parent;var animator=model.GetComponent<Animator>();if(animator==null)animator=model.gameObject.AddComponent<Animator>();animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;var motion=sheep.GetComponent<SportsSheepMotion>();if(motion==null)motion=sheep.AddComponent<SportsSheepMotion>();foreach(var duplicate in sheep.GetComponentsInChildren<SportsSheepMotion>(true))if(duplicate!=motion)UnityEngine.Object.DestroyImmediate(duplicate);motion.animator=animator;motion.mover=mover;EditorUtility.SetDirty(motion);}
 static AnimatorController Create(){var vendor=AssetDatabase.LoadAllAssetsAtPath(Model).OfType<AnimationClip>().First(x=>x.name=="RunCycle");var walk=UnityEngine.Object.Instantiate(vendor);walk.name="Genuine SheepV5 looping locomotion";var settings=AnimationUtility.GetAnimationClipSettings(walk);settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(walk,settings);AssetDatabase.CreateAsset(walk,Root+"SheepV5 locomotion.anim");var idle=UnityEngine.Object.Instantiate(vendor);idle.name="SheepV5 standing idle";foreach(var binding in AnimationUtility.GetCurveBindings(idle)){var curve=AnimationUtility.GetEditorCurve(vendor,binding);float value=curve.Evaluate(0);var pose=AnimationCurve.Constant(0,2.5f,value);if(binding.path.EndsWith("/Head")&&binding.propertyName=="m_LocalRotation.y")pose=new AnimationCurve(new Keyframe(0,value),new Keyframe(.625f,value+.025f),new Keyframe(1.875f,value-.025f),new Keyframe(2.5f,value));AnimationUtility.SetEditorCurve(idle,binding,pose);}settings=AnimationUtility.GetAnimationClipSettings(idle);settings.loopTime=true;settings.stopTime=2.5f;AnimationUtility.SetAnimationClipSettings(idle,settings);AssetDatabase.CreateAsset(idle,Root+"SheepV5 standing idle.anim");var result=AnimatorController.CreateAnimatorControllerAtPath(Root+"Sheep locomotion.controller");result.AddParameter("Speed",AnimatorControllerParameterType.Float);result.AddParameter("CycleSpeed",AnimatorControllerParameterType.Float);var state=result.layers[0].stateMachine;var rest=state.AddState("Standing idle");rest.motion=idle;state.defaultState=rest;var moving=state.AddState("Walk and run");moving.motion=walk;moving.speedParameter="CycleSpeed";moving.speedParameterActive=true;var start=rest.AddTransition(moving);start.hasExitTime=false;start.duration=.12f;start.AddCondition(AnimatorConditionMode.Greater,.15f,"Speed");var stop=moving.AddTransition(rest);stop.hasExitTime=false;stop.duration=.15f;stop.AddCondition(AnimatorConditionMode.Less,.1f,"Speed");AssetDatabase.SaveAssets();return result;}
}
}


